
-- Seed device reviews (Part 2) -- 4 reviews per device = 32 total
INSERT INTO public.device_reviews (device_id, user_id, title, content, rating, pros, cons, ownership_duration, verified_owner) VALUES
-- Dexcom G7
('b2a363a3-bc85-40a0-9bf6-4d1323d6ce0c', '00000000-0000-0000-0000-000000000001', 'Game changer for my management', 'The G7 has been incredible. 30-minute warmup vs 2 hours on G6. Much smaller sensor too. Accuracy has been excellent — within 5-10 points of my meter most of the time.', 5, ARRAY['Fast warmup', 'Small size', 'Excellent accuracy'], ARRAY['Occasional signal loss', 'Adhesive can irritate skin'], '6 months', true),
('b2a363a3-bc85-40a0-9bf6-4d1323d6ce0c', '00000000-0000-0000-0000-000000000002', 'Good but not perfect', 'Upgraded from G6. Love the smaller profile but I do get more compression lows at night. The app integration is solid though.', 4, ARRAY['Compact design', 'Good app'], ARRAY['Compression lows', 'Shorter sensor life'], '3 months', true),
('b2a363a3-bc85-40a0-9bf6-4d1323d6ce0c', '00000000-0000-0000-0000-000000000003', 'Best CGM I have used', 'Tried Libre and Medtronic sensors before. Dexcom G7 is the most accurate and reliable. The alerts have saved me from several dangerous lows.', 5, ARRAY['Reliable alerts', 'Accurate readings', 'Easy insertion'], ARRAY['Price without insurance'], '1 year', true),
('b2a363a3-bc85-40a0-9bf6-4d1323d6ce0c', '00000000-0000-0000-0000-000000000004', 'Solid upgrade from G6', 'Less bulky, faster startup. Wish it lasted more than 10 days though. Overall very happy with the switch.', 4, ARRAY['Slim profile', '30-min warmup'], ARRAY['10-day wear only', 'Adhesive issues in summer'], '4 months', true),

-- Dexcom G6
('8ecda931-a07b-4ceb-8dcc-7abce45d263b', '00000000-0000-0000-0000-000000000005', 'Reliable workhorse', 'Been on G6 for over a year. Rock solid accuracy. The 10-day sensor life is great. Integration with Tandem pump is seamless.', 5, ARRAY['10-day sensors', 'Pump integration', 'Share feature'], ARRAY['Transmitter replacement every 3 months', 'Bulkier than G7'], '1 year', true),
('8ecda931-a07b-4ceb-8dcc-7abce45d263b', '00000000-0000-0000-0000-000000000006', 'Changed my life as a parent', 'My 8-year-old wears this and the Share feature lets me monitor from my phone. Peace of mind is priceless.', 5, ARRAY['Share/Follow feature', 'Accurate', 'Easy for kids'], ARRAY['Inserter can be scary for children'], '2 years', true),
('8ecda931-a07b-4ceb-8dcc-7abce45d263b', '00000000-0000-0000-0000-000000000007', 'Good but ready for G7', 'G6 has been solid but the warmup time and size make me want to upgrade to G7. Still a great device overall.', 4, ARRAY['Proven technology', 'Good accuracy'], ARRAY['2-hour warmup', 'Larger than competitors'], '8 months', true),
('8ecda931-a07b-4ceb-8dcc-7abce45d263b', '00000000-0000-0000-0000-000000000008', 'My first CGM experience', 'Going from fingersticks to G6 was life-changing. I can finally see my glucose trends and patterns. A1C dropped 1.2% in 3 months.', 5, ARRAY['Trend arrows', 'Customizable alerts', 'Great reports'], ARRAY['Learning curve with app'], '6 months', true),

-- Omnipod 5
('444aafd0-91dc-4c48-94ec-8197a27506ee', '00000000-0000-0000-0000-000000000009', 'Tubeless freedom', 'Switched from Medtronic and never looking back. No tubes means I can swim, shower, and sleep without worrying. The automation with Dexcom is amazing.', 5, ARRAY['No tubes', 'Waterproof', 'Automated mode'], ARRAY['Pod can be knocked off', 'Limited customization'], '6 months', true),
('444aafd0-91dc-4c48-94ec-8197a27506ee', '00000000-0000-0000-0000-000000000010', 'Great for active lifestyle', 'I run marathons with this pump. It stays on through sweat and movement. The SmartAdjust algorithm keeps me in range most of the time.', 4, ARRAY['Active lifestyle friendly', 'Good algorithm', 'Discreet'], ARRAY['Cannot fine-tune basal rates in auto', 'Phone dependency'], '1 year', true),
('444aafd0-91dc-4c48-94ec-8197a27506ee', '00000000-0000-0000-0000-000000000011', 'Pod failures are frustrating', 'Love the concept but I get maybe 1-2 pod failures per box of 10. When it works, its amazing. Customer service is good about replacing them.', 3, ARRAY['Tubeless design', 'Good customer service'], ARRAY['Pod failures', 'Waste from disposable pods', 'Bulky for slim people'], '9 months', true),
('444aafd0-91dc-4c48-94ec-8197a27506ee', '00000000-0000-0000-0000-000000000012', 'My daughter loves it', 'She is 12 and was embarrassed by tube pumps. Omnipod 5 lets her wear it discreetly and the closed loop keeps her in range at school.', 5, ARRAY['Kid-friendly', 'Discreet', 'Automated dosing'], ARRAY['Learning the app takes time'], '4 months', true),

-- Tandem t:slim X2
('ee6d187d-b9aa-4054-aa50-7ea8aa2ad469', '00000000-0000-0000-0000-000000000013', 'Best pump on the market', 'Control-IQ is incredible. My TIR went from 55% to 78% within the first month. The touchscreen is intuitive and the cartridge change is easy.', 5, ARRAY['Control-IQ algorithm', 'Touchscreen', 'Software updates'], ARRAY['Tubing', 'Charging required'], '1 year', true),
('ee6d187d-b9aa-4054-aa50-7ea8aa2ad469', '00000000-0000-0000-0000-000000000014', 'Solid pump with great features', 'Upgraded from Medtronic 670G. The touchscreen and Dexcom integration make a huge difference. Control-IQ works well overnight.', 4, ARRAY['Dexcom integration', 'Exercise mode', 'Sleep mode'], ARRAY['Battery life could be better', 'Cartridge holds only 300u'], '8 months', true),
('ee6d187d-b9aa-4054-aa50-7ea8aa2ad469', '00000000-0000-0000-0000-000000000015', 'Night time control is excellent', 'Sleep Activity mode keeps me between 112-120 all night. Daytime can be trickier with meals but overall very impressed.', 4, ARRAY['Sleep mode is superb', 'Rechargeable', 'Good bolus calculator'], ARRAY['Meal bolusing timing matters', 'Screen can be hard to read in sunlight'], '6 months', true),
('ee6d187d-b9aa-4054-aa50-7ea8aa2ad469', '00000000-0000-0000-0000-000000000016', 'Worth every penny', 'My A1C went from 8.1 to 6.8 in 6 months. The technology handles the heavy lifting. I still count carbs but Control-IQ corrects my mistakes.', 5, ARRAY['Excellent outcomes', 'Auto-correction boluses', 'Good training resources'], ARRAY['Initial setup is complex'], '7 months', true),

-- Medtronic 780G
('bc513878-a799-4fa9-9e08-93f889ce196a', '00000000-0000-0000-0000-000000000017', 'Much improved over 670G', 'The 780G is a huge step up. Auto mode stays on much more consistently and the target can be set to 100 mg/dL. Guardian 4 sensor is better too.', 4, ARRAY['Improved algorithm', 'Lower target option', 'Better sensor'], ARRAY['Calibrations still needed sometimes', 'Bulky compared to competitors'], '5 months', true),
('bc513878-a799-4fa9-9e08-93f889ce196a', '00000000-0000-0000-0000-000000000018', 'Getting better but still behind', 'Medtronic has improved a lot but Tandem and Omnipod are still ahead in user experience. The algorithm works well when it stays in auto mode.', 3, ARRAY['Auto mode improvements', 'Meal detection'], ARRAY['Exits auto mode too often', 'App is clunky', 'Guardian sensor less accurate than Dexcom'], '3 months', true),
('bc513878-a799-4fa9-9e08-93f889ce196a', '00000000-0000-0000-0000-000000000019', 'Decent closed loop system', 'Does what it says. Keeps me in range about 70% of the time. The meal announcement feature helps with post-meal spikes.', 4, ARRAY['Meal announcement', 'Auto corrections', 'Long pump warranty'], ARRAY['User interface dated', 'Sensor tape issues'], '1 year', true),
('bc513878-a799-4fa9-9e08-93f889ce196a', '00000000-0000-0000-0000-000000000020', 'Loyal Medtronic user', 'Been with Medtronic for 15 years. Each generation gets better. 780G finally feels competitive with other systems.', 4, ARRAY['Familiar ecosystem', 'Good customer support', 'Extended warranty'], ARRAY['Slow to innovate', 'Proprietary sensors'], '6 months', true),

-- Freestyle Libre 3
('859a3182-60ab-48d6-8a87-3867c7bd1351', '00000000-0000-0000-0000-000000000021', 'Smallest CGM available', 'The Libre 3 is tiny — you forget it is there. Real-time readings without scanning is a big upgrade from Libre 2. Great for someone new to CGM.', 5, ARRAY['Tiny sensor', 'Real-time readings', 'No scanning needed', 'Affordable'], ARRAY['No Share/Follow feature yet in US', '14-day only'], '4 months', true),
('859a3182-60ab-48d6-8a87-3867c7bd1351', '00000000-0000-0000-0000-000000000022', 'Best value CGM', 'Half the cost of Dexcom with comparable accuracy. The app is clean and the sensor insertion is painless.', 4, ARRAY['Affordable', 'Painless insertion', 'Good accuracy'], ARRAY['Limited pump integration', 'No receiver option'], '6 months', true),
('859a3182-60ab-48d6-8a87-3867c7bd1351', '00000000-0000-0000-0000-000000000023', 'Good entry-level CGM', 'My endo recommended this as my first CGM. Easy to use and affordable. I can see my glucose trends for the first time.', 4, ARRAY['Easy setup', 'Good for beginners', 'Accurate after day 1'], ARRAY['First day readings can be off', 'Adhesive wears off in heat'], '2 months', true),
('859a3182-60ab-48d6-8a87-3867c7bd1351', '00000000-0000-0000-0000-000000000024', 'Great but want pump integration', 'Love the sensor but I wish it worked with more insulin pumps. Using it standalone is great though.', 4, ARRAY['Discreet', 'Comfortable', '1-minute warmup'], ARRAY['Limited closed-loop compatibility'], '5 months', true),

-- Beta Bionics iLet
('303a4259-fc00-4b86-b146-4b4172ef8c88', '00000000-0000-0000-0000-000000000025', 'Simplest pump ever', 'You literally just enter your weight and it figures everything out. No carb ratios, no correction factors, no basal rates. Revolutionary for people overwhelmed by pump settings.', 5, ARRAY['No settings to configure', 'Learns automatically', 'Great for pump newbies'], ARRAY['Cannot fine-tune if you want control', 'New to market'], '2 months', true),
('303a4259-fc00-4b86-b146-4b4172ef8c88', '00000000-0000-0000-0000-000000000026', 'Interesting concept, needs refinement', 'The idea of zero configuration is appealing but sometimes I want more control. It takes a few days to learn your patterns.', 3, ARRAY['Easy setup', 'Good concept'], ARRAY['Learning period', 'Cannot override algorithm easily', 'Limited to Dexcom sensors'], '1 month', true),
('303a4259-fc00-4b86-b146-4b4172ef8c88', '00000000-0000-0000-0000-000000000027', 'Perfect for my teenager', 'My 16-year-old refused to learn pump settings. iLet just works — enter weight and go. His A1C improved without any effort on his part.', 5, ARRAY['Zero configuration', 'Teen-friendly', 'Automatic adjustments'], ARRAY['Battery life average', 'Tubing'], '3 months', true),
('303a4259-fc00-4b86-b146-4b4172ef8c88', '00000000-0000-0000-0000-000000000028', 'The future of insulin pumps', 'This is what all pumps should be like. Let the algorithm do the work. My TIR is 75% without me doing anything beyond entering carb amounts.', 4, ARRAY['Fully automated', 'Simple meal bolusing', 'Good TIR results'], ARRAY['New product, limited long-term data'], '4 months', true),

-- Tandem Mobi
('704f508d-68c1-4396-a090-b8bb10ed7c5a', '00000000-0000-0000-0000-000000000029', 'Smallest tubed pump', 'The Mobi is incredibly small. It clips right to my waistband and I barely notice it. Control-IQ works just as well as on the t:slim.', 5, ARRAY['Ultra compact', 'Control-IQ included', 'Bluetooth to phone'], ARRAY['Small screen on pump', 'New product'], '2 months', true),
('704f508d-68c1-4396-a090-b8bb10ed7c5a', '00000000-0000-0000-0000-000000000030', 'Love the size, miss the screen', 'Coming from t:slim X2, the Mobi is so much smaller. But I do miss having a full touchscreen on the pump. The phone app handles most things though.', 4, ARRAY['Tiny form factor', 'Phone control', 'Same algorithm'], ARRAY['Tiny pump screen', 'Must carry phone'], '3 months', true),
('704f508d-68c1-4396-a090-b8bb10ed7c5a', '00000000-0000-0000-0000-000000000031', 'Great for active people', 'I CrossFit 5 days a week and the Mobi stays out of the way. Clip it to your shorts and forget about it. Control-IQ handles exercise well.', 5, ARRAY['Exercise friendly', 'Lightweight', 'Durable'], ARRAY['Limited cartridge size'], '4 months', true),
('704f508d-68c1-4396-a090-b8bb10ed7c5a', '00000000-0000-0000-0000-000000000032', 'Solid first pump choice', 'This was my first insulin pump ever. The small size made it less intimidating. Happy with my choice.', 4, ARRAY['Non-intimidating size', 'Good support resources', 'Modern design'], ARRAY['Learning curve for first-time pumpers'], '1 month', true);

-- Seed medication reviews (Part 3) -- 4 reviews per medication for top 10 meds = 40 total
INSERT INTO public.medication_reviews (medication_id, user_id, rating, effectiveness_rating, side_effects_rating, ease_of_use_rating, title, content, pros, cons, duration_of_use) VALUES
-- Humalog
('5a5cefcc-2092-4e7e-bff7-476d86c67c8e', '00000000-0000-0000-0000-000000000001', 5, 5, 4, 5, 'Gold standard rapid-acting', 'Been using Humalog for 12 years. Reliable, fast onset (15 min), predictable action. Works great in my pump. My go-to insulin.', ARRAY['Fast acting', 'Predictable', 'Works in pumps'], ARRAY['Expensive without insurance', 'Can cause lows if miscalculated'], '10+ years'),
('5a5cefcc-2092-4e7e-bff7-476d86c67c8e', '00000000-0000-0000-0000-000000000002', 4, 4, 4, 5, 'Reliable but pricey', 'Humalog works well but the cost is brutal without good insurance. Switched to Admelog for a while but came back — Humalog just works better for me.', ARRAY['Consistent results', 'Well-studied'], ARRAY['High list price', 'Generic alternatives available'], '5 years'),
('5a5cefcc-2092-4e7e-bff7-476d86c67c8e', '00000000-0000-0000-0000-000000000003', 5, 5, 5, 5, 'Life saver - literally', 'As a T1D for 20 years, Humalog has been my constant companion. The pen is easy to use and dosing is precise.', ARRAY['Easy pen delivery', 'Precise dosing', 'Proven track record'], ARRAY['Must refrigerate unused pens'], '15+ years'),
('5a5cefcc-2092-4e7e-bff7-476d86c67c8e', '00000000-0000-0000-0000-000000000004', 4, 5, 3, 4, 'Works great but watch for lows', 'Very effective at controlling post-meal spikes. However, I have to be careful with dosing as it can cause hypoglycemia if I miscalculate carbs.', ARRAY['Effective for meals', 'Fast onset'], ARRAY['Hypoglycemia risk', 'Weight gain possible'], '3 years'),

-- Novolog
('7c7398b1-beb1-4249-ad9d-543cf3808923', '00000000-0000-0000-0000-000000000005', 5, 5, 4, 5, 'My preferred rapid insulin', 'Tried Humalog and Novolog — I get slightly faster action with Novolog. Works perfectly in my Omnipod. Very satisfied.', ARRAY['Slightly faster than Humalog for me', 'Good pump compatibility', 'FlexPen is great'], ARRAY['Similar pricing issues as Humalog'], '7 years'),
('7c7398b1-beb1-4249-ad9d-543cf3808923', '00000000-0000-0000-0000-000000000006', 4, 4, 4, 4, 'Solid rapid-acting option', 'Very comparable to Humalog. My insurance covers Novolog better so that is what I use. No complaints about effectiveness.', ARRAY['Insurance preferred', 'Reliable action', 'Multiple delivery options'], ARRAY['Tail action can cause late lows'], '4 years'),
('7c7398b1-beb1-4249-ad9d-543cf3808923', '00000000-0000-0000-0000-000000000007', 5, 5, 5, 5, 'Been on it since diagnosis', 'Diagnosed T1D at age 10, now 28. Novolog has been my rapid insulin the whole time. Never had a reason to switch.', ARRAY['Long personal history', 'Consistent manufacturing', 'PenFill cartridges'], ARRAY['None significant'], '18 years'),
('7c7398b1-beb1-4249-ad9d-543cf3808923', '00000000-0000-0000-0000-000000000008', 4, 4, 3, 4, 'Good but Fiasp is faster', 'Novolog served me well for years but I recently switched to Fiasp for even faster action. Novolog is still a solid choice.', ARRAY['Well-established', 'Widely available'], ARRAY['Slower onset than ultra-rapid options', 'Injection site bumps occasionally'], '6 years'),

-- Lantus
('d1324095-2f44-4d5a-b778-cd47d66a2c6f', '00000000-0000-0000-0000-000000000009', 4, 4, 3, 5, 'Reliable basal coverage', 'Lantus gives me solid 24-hour basal coverage. One injection a day is convenient. Some stinging on injection but manageable.', ARRAY['Once daily dosing', '24-hour coverage', 'Stable levels'], ARRAY['Stings on injection', 'Cannot be mixed', 'Some peak activity'], '8 years'),
('d1324095-2f44-4d5a-b778-cd47d66a2c6f', '00000000-0000-0000-0000-000000000010', 3, 3, 3, 4, 'Works but Tresiba is better', 'Used Lantus for 5 years before switching to Tresiba. Lantus works fine but I noticed more variability in my fasting numbers. Tresiba is flatter.', ARRAY['Affordable with insurance', 'Proven technology'], ARRAY['Some day-to-day variability', 'Injection site reactions', 'Peak can cause lows'], '5 years'),
('d1324095-2f44-4d5a-b778-cd47d66a2c6f', '00000000-0000-0000-0000-000000000011', 5, 5, 4, 5, 'Staple of my regimen', 'Taking Lantus at bedtime along with Humalog for meals. This combo has kept my A1C under 7 for years. Very reliable.', ARRAY['Bedtime dosing works well', 'Consistent supply', 'SoloSTAR pen is easy'], ARRAY['pH is acidic — occasional sting'], '12 years'),
('d1324095-2f44-4d5a-b778-cd47d66a2c6f', '00000000-0000-0000-0000-000000000012', 4, 4, 4, 5, 'Great for MDI regimen', 'Paired with a rapid insulin, Lantus covers my basal needs perfectly. Simple once-daily injection.', ARRAY['Simple regimen', 'Predictable', 'Good pen design'], ARRAY['Not truly peakless'], '3 years'),

-- Tresiba
('684a65f8-09a6-4041-8e36-c94623fe9595', '00000000-0000-0000-0000-000000000013', 5, 5, 5, 5, 'Flattest basal insulin ever', 'Switched from Lantus and immediately noticed more stable overnight numbers. Tresiba truly has no peak. My fasting glucose is consistently 90-110.', ARRAY['Ultra-long 42h duration', 'No peak', 'Flexible dosing window'], ARRAY['Takes 3-4 days to reach steady state', 'Expensive'], '2 years'),
('684a65f8-09a6-4041-8e36-c94623fe9595', '00000000-0000-0000-0000-000000000014', 5, 5, 5, 5, 'Best basal insulin available', 'The 42-hour duration means you can flex your injection time by several hours without issues. Game changer for my irregular schedule.', ARRAY['Flexible timing', 'Rock-solid levels', 'Once daily'], ARRAY['Higher cost', 'Slow dose adjustments needed'], '1 year'),
('684a65f8-09a6-4041-8e36-c94623fe9595', '00000000-0000-0000-0000-000000000015', 4, 5, 4, 5, 'Worth the switch from Lantus', 'My endo suggested Tresiba and I am glad I listened. Less hypoglycemia overnight and more consistent daytime basals.', ARRAY['Less nighttime hypos', 'Consistent levels', 'FlexTouch pen'], ARRAY['Insurance may prefer Lantus'], '8 months'),
('684a65f8-09a6-4041-8e36-c94623fe9595', '00000000-0000-0000-0000-000000000016', 5, 5, 5, 4, 'The gold standard for basal', 'After trying Levemir, Lantus, and Basaglar, Tresiba is the clear winner. Flattest profile and least variability.', ARRAY['Minimal variability', 'Long proven track record', 'Multiple concentrations available'], ARRAY['U-200 pen math can confuse people'], '3 years'),

-- Fiasp
('e1f816a0-774c-4439-9c89-024dbef79b58', '00000000-0000-0000-0000-000000000017', 4, 5, 3, 4, 'Fastest insulin I have tried', 'Fiasp starts working in about 5 minutes. Perfect for when I forget to pre-bolus. Post-meal spikes are noticeably reduced.', ARRAY['Ultra-fast onset', 'Great for late bolusing', 'Reduces spikes'], ARRAY['Burns on injection', 'More expensive than Novolog', 'Shorter tail'], '1 year'),
('e1f816a0-774c-4439-9c89-024dbef79b58', '00000000-0000-0000-0000-000000000018', 3, 4, 2, 4, 'Fast but painful', 'The speed is amazing — I can bolus right when I eat. But the injection site stinging is real. Some sites burn more than others.', ARRAY['Very fast action', 'No pre-bolus needed often'], ARRAY['Injection pain', 'Site irritation', 'Can occlude pump sites faster'], '6 months'),
('e1f816a0-774c-4439-9c89-024dbef79b58', '00000000-0000-0000-0000-000000000019', 5, 5, 4, 5, 'Perfect for my pump', 'Using Fiasp in my Tandem pump has been great. The faster onset works beautifully with Control-IQ. My time-in-range improved by 10%.', ARRAY['Excellent in pumps', 'Faster corrections', 'Improved TIR'], ARRAY['Must watch for occlusions'], '8 months'),
('e1f816a0-774c-4439-9c89-024dbef79b58', '00000000-0000-0000-0000-000000000020', 4, 5, 3, 4, 'Game changer for meal management', 'I struggled with post-meal spikes for years. Fiasp nearly eliminated them. I can eat and bolus simultaneously now.', ARRAY['Eliminates post-meal spikes', 'Works within minutes', 'Pen and vial options'], ARRAY['Occasional burning sensation', 'Higher cost'], '4 months'),

-- Metformin
('4fa1a18f-5ab6-493b-a7d7-87d20141f449', '00000000-0000-0000-0000-000000000021', 4, 4, 2, 5, 'Helpful adjunct for T1D', 'My endo added Metformin to reduce my insulin needs. It cut my daily dose by about 15%. Some GI issues at first but they settled.', ARRAY['Reduces insulin needs', 'Cheap', 'Well-studied safety profile'], ARRAY['GI side effects initially', 'Must monitor B12 levels', 'Taste'], '2 years'),
('4fa1a18f-5ab6-493b-a7d7-87d20141f449', '00000000-0000-0000-0000-000000000022', 3, 3, 2, 4, 'Mixed results for me', 'Tried Metformin as an adjunct therapy. Some benefit for insulin sensitivity but the stomach issues were tough to manage.', ARRAY['Improved insulin sensitivity', 'Affordable generic'], ARRAY['Stomach cramps', 'Diarrhea first month', 'Metallic taste'], '6 months'),
('4fa1a18f-5ab6-493b-a7d7-87d20141f449', '00000000-0000-0000-0000-000000000023', 4, 4, 3, 5, 'Extended release is the way', 'Switched to Metformin ER and the GI issues disappeared. Now I get the insulin-sensitizing benefits without the stomach problems.', ARRAY['ER formulation better tolerated', 'Once daily', 'Insulin dose reduction'], ARRAY['Must take with food', 'Regular kidney function checks needed'], '1 year'),
('4fa1a18f-5ab6-493b-a7d7-87d20141f449', '00000000-0000-0000-0000-000000000024', 5, 5, 3, 5, 'Great addition to T1D management', 'Using Metformin with my insulin pump. My total daily dose dropped from 45u to 38u and my weight stabilized.', ARRAY['Weight neutral/loss', 'Cardiovascular benefits', 'Reduces insulin resistance'], ARRAY['Initial GI adjustment period'], '3 years'),

-- Jardiance
('055426fe-358d-4b67-b0eb-343f2433e635', '00000000-0000-0000-0000-000000000025', 4, 4, 3, 5, 'Helpful for kidney protection', 'My endo prescribed Jardiance for kidney and heart protection. A1C dropped slightly and my blood pressure improved too.', ARRAY['Cardiovascular protection', 'Kidney protection', 'Small A1C reduction'], ARRAY['Increased urination', 'UTI risk', 'DKA risk in T1D'], '1 year'),
('055426fe-358d-4b67-b0eb-343f2433e635', '00000000-0000-0000-0000-000000000026', 3, 3, 2, 5, 'Benefits with risks', 'The cardioprotective effects are proven but the increased risk of DKA with T1D makes me cautious. My endo monitors closely.', ARRAY['Proven cardiovascular benefits', 'Easy oral tablet', 'Weight loss'], ARRAY['DKA risk in T1D', 'Genital infections', 'Dehydration risk'], '6 months'),
('055426fe-358d-4b67-b0eb-343f2433e635', '00000000-0000-0000-0000-000000000027', 4, 4, 3, 5, 'Adjunct therapy working well', 'Added to my T1D regimen for heart protection. Lost 8 pounds and insulin needs dropped slightly. Must stay hydrated.', ARRAY['Heart protection', 'Weight management', 'Once daily pill'], ARRAY['Must drink lots of water', 'Occasional yeast infections'], '8 months'),
('055426fe-358d-4b67-b0eb-343f2433e635', '00000000-0000-0000-0000-000000000028', 5, 5, 4, 5, 'Important for long-term health', 'The EMPA-REG OUTCOME trial convinced my endo to prescribe this. Feel good about the long-term kidney and heart protection.', ARRAY['Evidence-based protection', 'Well-tolerated for me', 'Complements insulin therapy'], ARRAY['Extra monitoring needed'], '2 years'),

-- Ozempic
('c13a98c8-b910-4f41-a78a-189f7c259031', '00000000-0000-0000-0000-000000000029', 4, 4, 2, 4, 'Helps with insulin resistance', 'Using low-dose Ozempic off-label for insulin resistance with T1D. Reduced my daily insulin by 20% and lost some weight. Nausea was rough initially.', ARRAY['Reduced insulin needs', 'Weight loss', 'Weekly injection'], ARRAY['Severe nausea first month', 'Very expensive', 'Off-label for T1D'], '4 months'),
('c13a98c8-b910-4f41-a78a-189f7c259031', '00000000-0000-0000-0000-000000000030', 3, 3, 1, 4, 'Could not tolerate the side effects', 'Tried Ozempic for 2 months. The appetite suppression and weight loss were great but the nausea made it unbearable. Had to stop.', ARRAY['Significant appetite reduction', 'Weight loss effective'], ARRAY['Persistent nausea', 'Vomiting', 'Very expensive even with insurance'], '2 months'),
('c13a98c8-b910-4f41-a78a-189f7c259031', '00000000-0000-0000-0000-000000000031', 5, 5, 3, 4, 'Transformative for my T1D', 'Low dose Ozempic has been amazing. My insulin sensitivity improved dramatically. Went from 50u/day to 35u/day. Nausea subsided after 3 weeks.', ARRAY['Dramatic insulin reduction', 'Stable blood sugars', 'Less variability'], ARRAY['Initial nausea period', 'Shortage concerns', 'Insurance battles'], '6 months'),
('c13a98c8-b910-4f41-a78a-189f7c259031', '00000000-0000-0000-0000-000000000032', 4, 4, 3, 5, 'Weekly convenience is great', 'One injection per week beats daily pills. My fasting glucose improved and I need less correction insulin throughout the day.', ARRAY['Weekly dosing', 'Improved fasting glucose', 'Pen is easy to use'], ARRAY['GI side effects', 'Must titrate slowly', 'Supply issues'], '3 months'),

-- Afrezza
('90307ac0-6b49-40dd-8cda-5983fb44d7cb', '00000000-0000-0000-0000-000000000033', 5, 5, 4, 3, 'Fastest insulin possible', 'Afrezza peaks in 12-15 minutes. Nothing else comes close. Perfect for correcting highs quickly. The inhaler takes practice but it is worth it.', ARRAY['Fastest onset available', 'Mimics natural insulin', 'Quick corrections'], ARRAY['Learning curve with inhaler', 'Must do lung function tests', 'Limited dose options'], '1 year'),
('90307ac0-6b49-40dd-8cda-5983fb44d7cb', '00000000-0000-0000-0000-000000000034', 4, 5, 3, 3, 'Game changer for corrections', 'I use Afrezza for corrections and my pump for meals. A high blood sugar comes down in 30 minutes instead of 2 hours.', ARRAY['Ultra-rapid corrections', 'No injection needed', 'Discreet to use'], ARRAY['Cannot use with lung disease', 'Dose increments are large', 'Mild cough'], '6 months'),
('90307ac0-6b49-40dd-8cda-5983fb44d7cb', '00000000-0000-0000-0000-000000000035', 4, 4, 3, 4, 'Unique delivery method', 'Inhaling insulin feels sci-fi. The speed is remarkable. I use it alongside my pump for quick fixes and meals I forgot to pre-bolus for.', ARRAY['Inhaled delivery', 'Ultra-fast peak', 'Good for spontaneous meals'], ARRAY['Pulmonary function monitoring', 'Limited cartridge sizes (4u, 8u, 12u)'], '8 months'),
('90307ac0-6b49-40dd-8cda-5983fb44d7cb', '00000000-0000-0000-0000-000000000036', 3, 4, 3, 2, 'Interesting but not for everyone', 'The speed is great but the lack of precise dosing (only 4u increments) makes it hard for carb-counting. Best as a supplement.', ARRAY['Rapid action', 'Needle-free'], ARRAY['Imprecise dosing', 'Insurance rarely covers', 'Lung function tests required', 'Short shelf life after opening'], '3 months'),

-- Basaglar
('a7cfe663-65ac-43f3-b520-b5ba2689eec1', '00000000-0000-0000-0000-000000000037', 4, 4, 4, 5, 'Affordable Lantus alternative', 'Basaglar works identically to Lantus for me at a lower cost. My insurance switched me and I noticed zero difference in my control.', ARRAY['Lower cost than Lantus', 'Same active ingredient', 'KwikPen is easy'], ARRAY['Some stigma around biosimilars', 'Slight sting like Lantus'], '2 years'),
('a7cfe663-65ac-43f3-b520-b5ba2689eec1', '00000000-0000-0000-0000-000000000038', 5, 5, 4, 5, 'Glad my insurance switched me', 'Was nervous about switching from Lantus but Basaglar is identical in effect. Saved significant money on copays.', ARRAY['Cost savings', 'Identical efficacy', 'Good pen design'], ARRAY['Limited pen size options'], '1 year'),
('a7cfe663-65ac-43f3-b520-b5ba2689eec1', '00000000-0000-0000-0000-000000000039', 4, 4, 3, 5, 'Good biosimilar option', 'Functions exactly like Lantus. One injection at bedtime keeps my basal needs covered. Affordable and effective.', ARRAY['Affordable', 'Once daily', 'Reliable coverage'], ARRAY['Same stinging as Lantus', 'Not available everywhere'], '6 months'),
('a7cfe663-65ac-43f3-b520-b5ba2689eec1', '00000000-0000-0000-0000-000000000040', 4, 4, 4, 4, 'Solid basal insulin', 'Using Basaglar as my basal with Novolog for meals. Great combo that keeps me in range. No issues with the biosimilar.', ARRAY['Proven biosimilar', 'Good 24h coverage', 'Compatible with my insurance'], ARRAY['Wish it was truly peakless like Tresiba'], '9 months');
